style='body{font:16px/1.65 system-ui,sans-serif;background:#f4f6fb;color:#182a3a;margin:0;padding:32px}main{max-width:1000px;margin:auto}h1{font:42px/1.2 Georgia,serif}a{color:#2359af}pre{background:#fff;border:1px solid #d4dce6;border-radius:12px;padding:22px;overflow:auto;font:13px/1.7 monospace}.table-wrap{overflow:auto;background:white;border-radius:8px;border:1px solid #d4dce6;margin:24px 0}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #d4dce6;padding:12px;text-align:left;vertical-align:top}th{font-size:13px}td{font-size:14px}nav{margin-bottom:30px}details{background:white;border:1px solid #d4dce6;border-radius:10px;padding:20px;margin:18px 0}summary{font-weight:600;cursor:pointer}.result{color:#087859;font:32px/1.3 Georgia,serif;padding:20px 0}@media(max-width:500px){body{padding:16px}h1{font-size:32px}pre{padding:12px}}'
def page(title,body):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' · Orchard</title><style>'+style+'</style><main><nav><a href="../index.html#home">← Orchard laboratory</a></nav>'+body+'</main></html>'
def table(headers,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
for i,(name,title) in enumerate(zip(names,titles),1):
    raw=(dest/(name+'_results.json')).read_text();p=json.loads(raw)
    summary=''
